<style>
  .head {
    display: flex;
    flex-direction: column;
    gap: 14px;
    margin-bottom: 48px;
  }

  .timeline {
    display: flex;
    flex-direction: column;
  }

  /* The rail column of the design, then the content. */
  .job {
    display: grid;
    grid-template-columns: 44px minmax(0, 1fr);
    gap: clamp(12px, 3vw, 32px);
    /* What `.dot`'s position is derived from below, shared with `.card` and `.logo` so
